rules.css:
/* 极光玻璃：深空底色 + 流动极光 + 毛玻璃面板，保留论坛全部功能 */
:root, :root .light-scheme, :root .dark-scheme {
  color-scheme: dark !important;
  --au-bg: #070912;
  --au-glass: rgba(16, 18, 36, .42);
  --au-glass-hi: rgba(40, 36, 80, .55);
  --au-line: rgba(255, 255, 255, .08);
  --au-text: #e9ebf8;
  --au-muted: #8d93b0;
  --au-violet: #8b6cff;
  --au-cyan: #2fd4ff;
  --au-pink: #ff5fae;
  --au-grad: linear-gradient(120deg, #8b6cff 0%, #2fd4ff 50%, #ff5fae 100%);
  --primary: #e9ebf8 !important; --primary-rgb: 233,235,248 !important;
  --secondary: #0b0e1a !important; --secondary-rgb: 11,14,26 !important;
  --tertiary: #9d86ff !important; --tertiary-rgb: 157,134,255 !important; --quaternary: #2fd4ff !important;
  --header_background: transparent !important; --header_primary: #e9ebf8 !important;
  --primary-very-low: rgba(255,255,255,.03) !important; --primary-low: rgba(255,255,255,.08) !important;
  --primary-low-mid: rgba(255,255,255,.22) !important; --primary-medium: #8d93b0 !important;
  --primary-high: #b3b8d4 !important; --primary-very-high: #d8dbef !important;
  --secondary-low: #2a2f45 !important; --secondary-medium: #4a5070 !important; --secondary-high: #8d93b0 !important; --secondary-very-high: #c9cde3 !important;
  --tertiary-very-low: rgba(139,108,255,.08) !important; --tertiary-low: rgba(139,108,255,.18) !important;
  --tertiary-medium: #7a63e6 !important; --tertiary-high: #b8a8ff !important;
  --highlight: rgba(47,212,255,.12) !important; --d-hover: rgba(255,255,255,.06) !important; --d-selected: rgba(139,108,255,.16) !important;
  --d-sidebar-background: transparent !important;
  --d-sidebar-highlight-background: rgba(139,108,255,.16) !important; --d-sidebar-highlight-color: #fff !important;
  --d-sidebar-active-background: linear-gradient(90deg, rgba(139,108,255,.28), rgba(47,212,255,.08)) !important;
  --d-sidebar-active-color: #fff !important;
  --d-content-background: transparent !important;
  --d-border-radius: 14px !important; --d-button-border-radius: 12px !important; --d-input-border-radius: 12px !important;
  --font-family: "Inter", "PingFang SC", "HarmonyOS Sans SC", "Microsoft YaHei UI", system-ui, sans-serif !important;
}

html { background: var(--au-bg) !important; }
body { background: transparent !important; }
body { font-family: var(--font-family) !important; }

/* 极光背景：三团模糊光斑缓慢漂移 */
body::before, body::after {
  content: "" !important; display: block !important; position: fixed !important; z-index: -1 !important; pointer-events: none;
  top: -20vmax; left: -20vmax; width: calc(100vw + 40vmax); height: calc(100vh + 40vmax);
}
body::before {
  background:
    radial-gradient(32vmax 26vmax at 30% 26%, rgba(124, 92, 255, .85), transparent 70%),
    radial-gradient(30vmax 22vmax at 72% 22%, rgba(0, 200, 255, .55), transparent 70%),
    radial-gradient(34vmax 26vmax at 68% 78%, rgba(255, 70, 160, .50), transparent 70%),
    radial-gradient(26vmax 20vmax at 26% 80%, rgba(40, 255, 200, .28), transparent 70%);
  filter: blur(30px) saturate(130%);
  animation: au-drift 26s ease-in-out infinite alternate;
}
body::after {
  top: 0; left: 0; width: 100vw; height: 100vh;
  background:
    radial-gradient(rgba(255,255,255,.7) 1px, transparent 1.4px) 0 0 / 120px 120px,
    radial-gradient(rgba(255,255,255,.5) 1px, transparent 1.2px) 60px 70px / 180px 180px,
    linear-gradient(180deg, rgba(7,9,18,.15), rgba(7,9,18,.55));
  opacity: .32;
}
@keyframes au-drift {
  0% { transform: translate3d(0, 0, 0) rotate(0deg); }
  50% { transform: translate3d(4vmax, -3vmax, 0) rotate(8deg); }
  100% { transform: translate3d(-3vmax, 3vmax, 0) rotate(-6deg); }
}
@media (prefers-reduced-motion: reduce) { body::before { animation: none; } }

/* 顶栏 */
.d-header {
  background: rgba(9, 11, 22, .55) !important;
  backdrop-filter: blur(20px) saturate(170%); -webkit-backdrop-filter: blur(20px) saturate(170%);
  border-bottom: 1px solid var(--au-line) !important; box-shadow: 0 10px 40px rgba(0,0,0,.25) !important;
}
.d-header .d-icon, .d-header .icon { color: #cfd3ea !important; }

/* 侧边栏 */
.sidebar-wrapper, .sidebar-footer-wrapper, .sidebar-container {
  background: transparent !important; border-right: none !important;
}
.sidebar-wrapper { border-right: 1px solid var(--au-line) !important; background: rgba(9, 11, 22, .35) !important; backdrop-filter: blur(16px); }
.sidebar-section-link { border-radius: 10px !important; transition: background .2s, transform .2s; }
.sidebar-section-link:hover { transform: translateX(3px); }
.sidebar-section-header-text { letter-spacing: .08em; }

/* 欢迎横幅：渐变标题 + 发光搜索框 */
.welcome-banner__title {
  background: var(--au-grad); background-size: 200% auto;
  -webkit-background-clip: text; background-clip: text; color: transparent !important;
  font-weight: 800 !important; letter-spacing: -.02em; font-size: 2.6em !important;
  animation: au-shine 8s linear infinite;
  filter: drop-shadow(0 6px 30px rgba(139,108,255,.45));
}
@keyframes au-shine { to { background-position: 200% center; } }
.search-input--welcome-banner {
  background: rgba(255,255,255,.06) !important; border: 1px solid rgba(255,255,255,.14) !important;
  border-radius: 16px !important; backdrop-filter: blur(14px);
  box-shadow: 0 0 0 4px rgba(139,108,255,.10), 0 18px 50px rgba(47,212,255,.16) !important;
  transition: box-shadow .25s, border-color .25s;
}
.search-input--welcome-banner:focus-within { border-color: rgba(47,212,255,.6) !important; box-shadow: 0 0 0 4px rgba(47,212,255,.18), 0 18px 60px rgba(139,108,255,.35) !important; }
.search-input--welcome-banner input.search-term__input {
  background: transparent !important; border: none !important; box-shadow: none !important; color: var(--au-text) !important;
}
.search-input--welcome-banner .search-icon { border: none !important; background: transparent !important; }

/* 公告条 */
.alert-global-notice, .alert.alert-info {
  background: linear-gradient(90deg, rgba(139,108,255,.18), rgba(47,212,255,.10)) !important;
  border: 1px solid rgba(139,108,255,.35) !important; border-radius: 14px !important; color: var(--au-text) !important;
  backdrop-filter: blur(12px);
}
.alert-global-notice a { color: var(--au-cyan) !important; }

/* 导航与按钮 */
#navigation-bar li a { border-radius: 10px !important; color: var(--au-muted) !important; }
#navigation-bar li a { border: none !important; box-shadow: none !important; }
#navigation-bar li a::after, #navigation-bar li a::before { display: none !important; }
#navigation-bar li.active > a {
  color: #fff !important; background: rgba(139,108,255,.20) !important;
  box-shadow: inset 0 0 0 1px rgba(157,134,255,.35) !important;
}
.btn-primary, .d-combo-button .btn {
  background: #6f5ce0 !important; border: none !important; color: #fff !important;
  box-shadow: 0 0 0 1px rgba(255,255,255,.10) inset !important; transition: background .2s;
}
.btn-primary:hover, .d-combo-button .btn:hover { background: #7d6cf0 !important; }
.d-combo-button .btn + .btn { border-left: 1px solid rgba(255,255,255,.18) !important; }
.btn-primary .d-icon { color: #fff !important; }
.select-kit-header, .category-breadcrumb .select-kit-header, .btn-default {
  background: var(--au-glass) !important; border: 1px solid var(--au-line) !important; border-radius: 12px !important;
}

/* 话题列表：每一行一张玻璃卡片 */
.topic-list { border-collapse: separate !important; border-spacing: 0 8px !important; }
.topic-list-header th { color: var(--au-muted) !important; font-weight: 600; letter-spacing: .04em; border: none !important; }
.topic-list-item {
  background: var(--au-glass) !important; border: none !important; backdrop-filter: blur(14px) saturate(150%);
  transition: background .2s, box-shadow .2s, transform .2s;
}
.topic-list-item > td { border: none !important; border-top: 1px solid var(--au-line) !important; border-bottom: 1px solid var(--au-line) !important; }
.topic-list-item > td:first-child { border-left: 1px solid var(--au-line) !important; border-radius: 14px 0 0 14px; }
.topic-list-item > td:last-child { border-right: 1px solid var(--au-line) !important; border-radius: 0 14px 14px 0; }
.topic-list-item:hover { background: var(--au-glass-hi) !important; }
.topic-list-item:hover > td { border-color: rgba(157,134,255,.38) !important; }
.topic-list-item.visited .title, .topic-list-item .title.visited { color: #9aa0bd !important; }
.topic-list .main-link a.title { color: #f1f2fb !important; font-weight: 600; }
.topic-list-item .num.views .number, .topic-list-item .num.posts-map a { font-variant-numeric: tabular-nums; }
.topic-list .heatmap-high, .topic-list .heatmap-high a { color: #ff7ab8 !important; }
.topic-list .heatmap-med, .topic-list .heatmap-med a { color: #ffa0cf !important; }
.topic-list .badge-notification.unread-posts, .badge-notification.new-topic, .topic-list .badge-notification {
  background: var(--au-grad) !important; color: #fff !important; box-shadow: 0 0 12px rgba(47,212,255,.6);
}
.topic-list .posters img.avatar { box-shadow: 0 0 0 2px rgba(11,14,26,.9); }

/* 标签 */
.discourse-tag.box {
  background: rgba(255,255,255,.05) !important; border: 1px solid rgba(255,255,255,.1) !important;
  border-radius: 999px !important; padding: 1px 8px !important; color: #c3c8e3 !important;
}

/* 分类卡片 */
.category-box, .category-boxes .category-box-inner, .category-list tbody tr {
  background: var(--au-glass) !important; border-radius: 14px !important; backdrop-filter: blur(10px);
}

/* 话题页 */
.post-stream .topic-post > article {
  background: rgba(14, 16, 32, .55) !important; border: 1px solid var(--au-line) !important; border-radius: 18px !important;
  backdrop-filter: blur(16px) saturate(150%); margin: 10px 0 !important; padding: 6px 10px 2px !important;
  box-shadow: 0 10px 40px rgba(0,0,0,.25);
}
.post-stream .topic-post .topic-body, .post-stream .topic-post .topic-avatar { border-top: none !important; }
.cooked aside.quote .title, .cooked blockquote {
  background: rgba(139,108,255,.10) !important; border-left: 3px solid var(--au-violet) !important; border-radius: 0 12px 12px 0;
}
.cooked aside.quote blockquote { background: rgba(255,255,255,.03) !important; border-left-color: rgba(47,212,255,.6) !important; }
.topic-post .cooked a { color: var(--au-cyan) !important; }
.cooked code, .cooked pre code { background: rgba(255,255,255,.06) !important; border-radius: 8px; }
.timeline-scrollarea .timeline-handle { background: var(--au-grad) !important; }

/* 弹出层与编辑器 */
.menu-panel, .user-menu, .search-menu .menu-panel, .select-kit-body, .popup-menu, #reply-control, .d-modal__container {
  background: rgba(14, 17, 32, .88) !important; backdrop-filter: blur(22px) saturate(160%);
  border: 1px solid var(--au-line) !important;
}

/* 滚动条 */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: linear-gradient(var(--au-violet), var(--au-cyan)); border-radius: 10px; border: 3px solid var(--au-bg); }
::-webkit-scrollbar-track { background: transparent; }
::selection { background: rgba(139,108,255,.45); color: #fff; }
